enum Step<T> { case done(T), more(() -> Step<T>) }

func even(_ n: Int) -> Step<Bool> { n == 0 ? .done(true) : .more { odd(n - 1) } }
func odd(_ n: Int) -> Step<Bool>  { n == 0 ? .done(false) : .more { even(n - 1) } }

func run<T>(_ step: Step<T>) -> T {
    var s = step
    while case let .more(next) = s { s = next() }
    guard case let .done(value) = s else { fatalError("unreachable") }
    return value
}
